window.addEventListener("DOMContentLoaded",function(){var n=document.querySelectorAll(".navbar-fixed-top");if(1<=n.length){function t(){window.scrollY>=n[0].getBoundingClientRect().bottom&&!n[0].classList.contains("navbar-transition")?n[0].classList.add("navbar-transition"):window.scrollY<n[0].getBoundingClientRect().bottom&&n[0].classList.contains("navbar-transition")&&n[0].classList.remove("navbar-transition")}["scroll","resize","DOMContentLoaded"].forEach(function(n){window.addEventListener(n,t)}),t()}});
